# @TracedIn('messaging.flows')  # generate_doc.py using ute_doc fails on generation for decorated functions
def get_flow(alias):
    """
    Return flow based on its alias.

    :param alias: alias to get flow object for
    :return: instance of MessageFlow class
    :raises: :py:class:`ute_common_abstract_core.exceptions.UnknownAlias`: if no such alias created before this call
    :raises: :py:class:`ute_common_abstract_core.exceptions.WrongAlias`: if alias doesn't point to MessageFlow object
    """
    location_info = "called from: 'get_flow(alias={})'".format(alias)
    expected_preceding_call_robot = "(robot API):  Expect Message Flow ...  {}"
    expected_preceding_call_python = "(python API): MessageFlow.expect_message_flow(alias={}, ...)"
    if alias not in aliases_registry():
        how_to_fix_msg = "you should precede it with starting flow of given alias via:"
        how_to_fix_info = "  {}\n    {}\n    {}".format(how_to_fix_msg,
                                                        expected_preceding_call_robot.format(alias),
                                                        expected_preceding_call_python.format(alias))
        raise UnknownAlias("{}\n{}".format(location_info, how_to_fix_info))
    flow = aliases_registry()[alias]
    if not isinstance(flow, MessageFlow):
        why_wrong_info = "should be alias of {} object but {} points to '{}' object".format(MessageFlow.__name__,
                                                                                            alias,
                                                                                            flow.__class__.__name__)
        how_to_fix_msg = "you should use FLOW_alias given via:"
        how_to_fix_info = "  {}\n    {}\n    {}".format(how_to_fix_msg,
                                                        expected_preceding_call_robot.format("FLOW_alias"),
                                                        expected_preceding_call_python.format("FLOW_alias"))
        raise WrongAlias("{}\n  {}\n  {}".format(location_info, why_wrong_info, how_to_fix_info))
    return flow


class NoException(Exception):
    pass


class FlowWithAliasIsStillRunning(AbstractUeLibException):
    """Cannot start new flow with the same alias until previos one finished"""
    def __init__(self, alias, assigned_object):
        """
        Basic initialization.

        :param alias:
        :param assigned_object:
        """
        super(FlowWithAliasIsStillRunning, self).__init__()
        self.alias = alias
        self.assigned_object = assigned_object  # TODO use it for global aliases testing (if alias4ue is DT used alias)

    def __str__(self):
        err = "alias '{}' already assigned to running flow'{}'\n" \
              "Alias can be re-used only when flow has ended (successfully or by timeout)\n" \
              "".format(self.alias, self.assigned_object)
        return err


class MessageFlow(object):
    """
    Entity responsible for capturing desired message.

    Defines two-step message verification:

    * precondition used by dispatcher composed of message_type and message_owner
    * optional verification_callback for more detailed matching
    """
    # todo different constructor for python object creation? from_...[message]list
    def __init__(self, name, timeout, message_list, publisher=None):
        """
        :param name: alias of the flow
        :param timeout:
        :param message_list: list of requirements for expected messages written in user friendly language.

        Encapsulates owner, message_type and conditions.
        """
        if not message_list:
            raise EmptyMessageList()
        self.name = name
        self._timeout = timeout
        self._publisher = publisher if publisher is not None else self._get_publisher()
        self.is_success = False
        self._cleanup = False
        self.msg_queue = Queue()
        self.logger = logging.getLogger('messaging.flows')
        self.logger_msgs = logging.getLogger('messaging.flows.logic')
        self._observer_list_lock = threading.Semaphore(1)
        self.flow_items = self._create_list_of_expected_messages_descriptions(message_list)
        self.ordered_observers_list = None
        self._hierarchical_structure_of_observers = {}
        self._observers_by_aliases = {}
        self._subscribed_observers = []  # subscribed_observers_data
        self._already_subscribed_flow_items = []
        self._active_observer = None
        self._exception = NoException()  # to make Lint happy
        self._dequeue_timeout = 0.01
        self.is_running = threading.Event()
        self._timeouted = False
        self.flow_already_ended_and_verified = False
        self.flow_already_ended_and_but_not_verified = False
        self._timer = threading.Timer(self._timeout, self._on_timeout)
        self._flow_started = threading.Semaphore(0)
        self._ended = threading.Semaphore(0)
        self._start_and_spawn_flow_loop_in_separate_thread()
        self._flow_started.acquire()
        msgs_list = [str(msg) for msg in message_list]
        awaited_list = ', '.join(msgs_list)
        self.logger_msgs.debug('%s started - awaiting %s sec for messages: %s' % (self, timeout, awaited_list))

    def __repr__(self):
        class_name = self.__class__.__name__
        queue_name = 'Que:{}'.format(hex(id(self.msg_queue)))  # important in debugs since it is used for subscriptions
        return '%s(%s, %s)' % (class_name, self.name, queue_name)

    def __str__(self):
        class_name = self.__class__.__name__
        return '%s(%s)' % (class_name, self.name)

    @classmethod
    def expect_message_flow(cls, alias, overall_timeout, awaited_messages):
        """
        Declare expected message flow for messages defined in awaited_messages list.

        It builds flow object that runs observer for each message to be caught.

        :param alias: alias of the flow
        :param overall_timeout: timeout of the flow
        :param awaited_messages: list of strings which define expected messages
        :return: MessageFlow instance
        """
        # todo use parameter_utils for time format
        msgs_list = [str(msg) for msg in awaited_messages]
        awaited_list = ', '.join(msgs_list)
        logger = logging.getLogger('messaging.flows')
        logger.info('Expect MessageFlow(%s, timeout %s sec) of %s' % (alias, overall_timeout, awaited_list))
        if alias in aliases_registry():
            previous_flow_with_same_alias = aliases_registry()[alias]
            if not isinstance(previous_flow_with_same_alias, MessageFlow):
                raise MessageFlowAliasAlreadyExistsAndNotAssignedToMessageFlowObject(previous_flow_with_same_alias)
            if not (previous_flow_with_same_alias.flow_already_ended_and_verified
                    or previous_flow_with_same_alias.flow_already_ended_and_but_not_verified):
                raise FlowWithAliasIsStillRunning(alias, previous_flow_with_same_alias)
            # allow scope to perform registered cleanup actions
            current_scope().release_resource(resource=[alias])  # [] required for current alias_registry release api
        flow = cls(alias, float(overall_timeout), awaited_messages)
        current_scope().uses(resource=flow, resource_releaser=flow.cleanup_flow)
        aliases_registry()[alias] = flow

        return flow

    @staticmethod
    @TracedIn('messaging.flows')
    def flow_occurred_as_expected(alias):
        """
        Checks if flow messages with given conditions occurred.

        Waits until success or timeout of the flow.

        :param alias: flow that is being checked
        :return: None
        :raises: :py:class:`ute_common_abstract_core.exceptions.UnknownAlias`: if no such alias created before this call
        :raises: :py:class:`ta_messaging.exceptions.NoMessageInFlow`: if any message of the flow is missing
        """
        if alias not in aliases_registry():
            location_info = "called from: 'Flow Occurred as Expected  alias={}'".format(alias)
            expected_preceding_call = "Expect Message Flow ...  alias={}".format(alias)
            how_to_fix_info = "  you should precede it with starting flow of given alias '{}'".format(expected_preceding_call)
            raise UnknownAlias(location_info + "\n" + how_to_fix_info)
        flow = aliases_registry()[alias]
        flow.logger.info('Checking if %s occurred as expected' % flow)
        flow.verify_flow_has_occurred()
        flow.logger.info('%s occurred as expected' % flow)

    def subscribe(self, expected_message_descriptions):
        """
        Subscribe itself to publisher for all expected messages.

        From now on publisher will be sending messages to this observer if condition (message type and owner) will be met.

        :param expected_message_descriptions:
        :return: None
        """
        for message_description in expected_message_descriptions:
            if message_description not in self._already_subscribed_flow_items:
                self._already_subscribed_flow_items.append(message_description)
                self._publisher.subscribe_observer(self.msg_queue, message_description.message_type, message_description.owner)
        self.logger.debug('%r subscribed at %s' % (self, self._publisher))

    def unsubscribe(self):
        """
        Unsubscribes itself from publisher.

        From now on publisher will not be sending messages to this observer.

        :return: None
        """
        self._publisher.unsubscribe_observer(self.msg_queue)
        self.logger.debug('%r unsubscribed from %s' % (self, self._publisher))

    def subscribe_observer(self, msg_queue, message_type, owner, is_running):
        """
        Allows observers to subscribe their interests in specific message type

        :param msg_queue: observers queue to which matching messages should be sent
        :param message_type: observers desired message type
        :param owner: observers desired message owner
        :param is_running: event holding information if observer is not in state of not accepting messages
        :return: None
        """
        observer_data = ObserverSelectedData(msg_queue, message_type, owner, is_running)

        self._subscribed_observers.append(observer_data)

    def unsubscribe_observer(self, observer_queue):
        """
        Allows observers to unsubscribe at their will

        :param observer_queue: observer queue of instance of MessageObserver that should be unsubscribed
        :return: None
        """
        self._observer_list_lock.acquire()
        self._subscribed_observers = [sub_obs for sub_obs in self._subscribed_observers if
                                      observer_queue is not sub_obs.msg_queue]
        self._observer_list_lock.release()

    def verify_flow_has_occurred(self):
        """
        Wait for flow success
        """
        self.logger.debug('%s main thread will block until flow ends' % self)
        if not self.flow_already_ended_and_verified:
            self._ended.acquire()
            # self.is_success
            self.flow_already_ended_and_verified = True
            self._verify_has_flow_succeed()
        else:
            self.logger.debug('%s has already succeeded and had been verified, skipping verification' % self)
        self.logger.debug('%s main thread successfully caught the flow' % self)

    def _verify_has_flow_succeed(self):
        if not isinstance(self._exception, NoException):
            # raise Exception(self._exception, self.name)
            raise self._exception
        for observer in self.ordered_observers_list:
            observer.verify_message_has_been_caught()

    @TracedIn('messaging.flows')
    def get_message(self, name):
        """
        Get message from flow instance.

        Message can be accessed by alias only or by key device+message_type+[occurence]

        :param name: alias name or full name with optional device and optional occurence
        :return: Message object instance

        e.g.::

            ext_req
            NAS_ExtendedServiceRequest[1]
            UE_1:NAS_ExtendedServiceRequest[1]
        """
        try:
            ExpectedMessageDescription._alias_template.parseString(name)
            return self._observers_by_aliases[name].get_message()
        except KeyError:
            pass

        try:
            message_getter_parsed = ExpectedMessageDescription._message_getter_template.parseString(name)
            msg_desc = ExpectedMessageDescription.wrap_message_description_to_structure(message_getter_parsed)
            return self._get_message_from_flow(msg_desc.owner.alias, msg_desc.message_type, msg_desc.occurrence)
        except ParseException:
            raise NoMessageInFlow(name)

    def stop(self):
        """
        Stop flow thread
        """
        self._timer.cancel()
        self._exit_flow_loop()
        self._ended.acquire()
        # todo this should be in
        for message_flow_item in self.ordered_observers_list:
            message_flow_item.stop()
        raise FlowStopped()

    def cleanup_flow(self, flow):
        """
        Cleanup flow thread
        TO BE REFACTORED FOR MORE GRACEFULL STOP WITHOUT USING TIMEOUT API
        """
        if self.is_running.is_set():
            self.logger.warning('%s performing cleanup. It should happen only when robot test fails with flow still running' % self)
            self._cleanup = True
            for observer in flow.ordered_observers_list:
                observer._on_stop()
            try:
                flow.stop()
            except FlowStopped:
                pass

    def _start_and_spawn_flow_loop_in_separate_thread(self):
        self._start()
        thread_name = "Flow-{}-Thread".format(self.name)
        threading.Thread(target=self._enter_flow_loop, name=thread_name).start()

    def _start(self):
        self.ordered_observers_list = self._create_observers(self.flow_items)
        self.subscribe(self.flow_items)
        self._hierarchical_structure_of_observers = self._create_tree_of_observers()
        self._observers_by_aliases = self._create_aliases_to_observers_mapping()
        self._wait_for_subscribers_and_sort()
        self._flow_started.release()
        self._timer.start()
        self.is_running.set()

    def _on_success(self):
        if self._timeouted is False:
            self._timer.cancel()
            self.is_success = True
            self.logger.debug('%s sets its status to success' % self)

    def _on_timeout(self):
        if not self.is_success:
            self._timeouted = True
            self.is_running.clear()
        else:
            #  print 'else'
            pass

    def _get_message_from_msg_queue(self):
        try:
            unparsed_msg = self.msg_queue.get(timeout=self._dequeue_timeout)
            self.logger.debug('%s received message %s of %s' % (self, unparsed_msg.message_type, unparsed_msg.owner))
            return unparsed_msg
        except Empty:
            return None

    def _find_messages_owner_in_message_buffer(self, owner_from_message, buffer):
        found_owners = []
        for stored_owner in list(buffer.keys()):
            # unhashed_key = json.loads(stored_owner)
            # network_elem_type = unhashed_key[0]
            # specific_for_tool = unhashed_key[1]
            # ids_of_stored_owner = unhashed_key[2].items()

            # ids_of_stored_owner = list(unhashed_key[1].items())
            # owner_already_stored = NetworkElementIdentification.from_type_id_pairs(identifiers=ids_of_stored_owner,
            #                                                                        network_elem_type=network_elem_type,
            #                                                                        # specific_for_tool=specific_for_tool
            #                                                                        )

            if buffer[stored_owner]['owner'] == owner_from_message:
                found_owners.append(stored_owner)
        if len(found_owners) == 1:
            return found_owners[0]
        elif len(found_owners) > 1:
            self.logger.error('Many messages ques: {} found in buffer for the same owner: {}'.format(found_owners, owner_from_message))
        return None

    def _find_owner_in_message_buffer(self, owner, buffer):
        matching_sources_in_buffer = []
        for stored_owner in list(buffer.keys()):
            # unhashed_key = json.loads(stored_owner)
            # network_elem_type = unhashed_key[0]
            # specific_for_tool = unhashed_key[1]
            # ids_of_stored_owner = unhashed_key[2].items()

            # ids_of_stored_owner = list(unhashed_key[1].items())
            # owner_already_stored = NetworkElementIdentification.from_type_id_pairs(identifiers=ids_of_stored_owner,
            #                                                                        network_elem_type=network_elem_type,
            #                                                                        # specific_for_tool=specific_for_tool
            #                                                                        )
            if buffer[stored_owner]['owner'] == owner:
                matching_sources_in_buffer.append(stored_owner)
        if len(matching_sources_in_buffer) > 1:
            self.logger.warn('Found multiple sources: {} for owner: {}, consider re-writing test such that messages'
                             ' are captured on unique owner'.format(matching_sources_in_buffer, owner))
        return matching_sources_in_buffer

    def _update_message_buffer(self, message_buffer):
        unparsed_msg_from_queue = self._get_message_from_msg_queue()
        if unparsed_msg_from_queue:
            stored_owner = self._find_messages_owner_in_message_buffer(unparsed_msg_from_queue.owner, message_buffer)
            if stored_owner is None:
                # stored_owner = json.dumps([unparsed_msg_from_queue.owner.network_elem_type,
                #                            # unparsed_msg_from_queue.owner.specific_for_tool,
                #                            dict(unparsed_msg_from_queue.owner)])
                stored_owner = str(unparsed_msg_from_queue.owner)
                message_buffer[stored_owner] = {'owner': unparsed_msg_from_queue.owner,
                                                'messages': []}
                # puts string representation of owner into dict, string is bidirectional, the same to [x,y] as for [y,x]
            message_buffer[stored_owner]['messages'].append(unparsed_msg_from_queue)
            self.logger.debug("%s moved message %s from queue to message buffer for owner %s" %
                              (self, unparsed_msg_from_queue.message_type, unparsed_msg_from_queue.owner))
        return message_buffer

    def _enter_flow_loop(self):
        """
        Starts flow loop

        Reads messages from flow_msg queue. If not consumed by observer, put it on skipped_message_queue for other
        observers.
        """
        self.logger.debug('{!r} thread started'.format(self))
        messages_buffer_per_source = {}
        try:
            self._update_active_observer()  # set active_observer
            while self.is_running.is_set():
                self._update_message_buffer(messages_buffer_per_source)
                sources_list = self._find_owner_in_message_buffer(self._active_observer.owner, messages_buffer_per_source)
                for source in sources_list:
                    if len(messages_buffer_per_source[source]['messages']):
                        unparsed_msg = messages_buffer_per_source[source]['messages'].pop(0)
                        subscriber_found = self._send_message_to_proper_subscribers(unparsed_msg)
                        self._wait_for_observer_to_consume_message(subscriber_found, unparsed_msg)
                self._update_active_observer()
            self._determine_result_on_flow_end()
        except MessageObserverTimeout as exc:
            self._exception = exc
            self.logger_msgs.debug('%s - TIMEOUT inside flow: Observer for msg:%s owner:%s timeouted' % (self, self._exception.message_type,
                                                                                                         self._exception.owner))
            self._exception.owning_flow = self
        except Exception as exc:
            self._exception = exc
            self.logger_msgs.debug('%s - Exception caught inside flow: %s' % (self, type(self._exception)))

        finally:
            self.is_running.clear()
            self._unsubscribe_from_publisher()
        self._ended.release()
        self.logger.debug('{!r} thread finished'.format(self))
        self.flow_already_ended_and_but_not_verified = True

    def _determine_result_on_flow_end(self):
        if not self._cleanup:
            self._verify_has_flow_succeed()
            self._on_success()

    def _unsubscribe_from_publisher(self):
        try:
            self.logger.debug('%r tries to unsubscribe from its publisher' % self)
            self.unsubscribe()
            self.logger.debug('%r unsubscribed successfully from its publisher' % self)
        except Exception:
            pass

    def _wait_for_observer_to_consume_message(self, subscriber_found, unparsed_msg):
        if subscriber_found:
            self._active_observer.msg_queue.join()
            self.logger.debug('%s item %s was consumed by %s' % (self, unparsed_msg.message_type,
                                                                 self._active_observer))
            msg_type = unparsed_msg.message_type
            if 'alias' in self._active_observer.owner:
                msg_type = "%s:%s" % (self._active_observer.owner['alias'], unparsed_msg.message_type)
            self.logger.info('%s - %s occurred' % (self, msg_type))
        else:
            self.logger.warning('%s item %s was not forwarded to any observer and deleted' % (self, unparsed_msg))

    def _get_publisher(self):
        mm = message_manager.MessageManager()
        publisher = mm._dispatcher
        return publisher

    def _create_list_of_expected_messages_descriptions(self, message_list):
        flow_item_list = []
        for index, msg in enumerate(message_list):
            item = FlowItem(msg, index)
            owner, message_type = item.owner, item.message_type
            # todo add test for occurrence when somebody dont use device_alias before message:
            #                         '          RRC_rrcConnectionRequest',     / occurrence=1
            #                         'UE1_ALIAS:RRC_rrcConnectionRequest',     / occurrence=2
            occurrence = self._get_message_occurrence(flow_item_list, message_type, owner)
            item.occurrence = occurrence
            flow_item_list.append(item)
        return flow_item_list

    def _get_message_occurrence(self, flow_item_list, message_type, owner):
        return sum([1 for existing_item in flow_item_list if existing_item.owner == owner and existing_item.message_type == message_type]) + 1

    def _create_observers(self, expected_message_descriptions):
        observers_list = []
        for message_description in expected_message_descriptions:
            observer = self._create_observer(message_description)
            observers_list.append(observer)
        return observers_list

    def _create_observer(self, message_description):
        observer = MessageObserver(publisher=self,
                                   protocol=message_description.protocol,
                                   message_type=message_description.message_type,
                                   owner=message_description.owner,
                                   timeout=self._timeout,
                                   verification_callback=message_description.verification_callback)

        self.logger.debug('%s started %s' % (self, observer))
        return observer

    def _wait_for_subscribers_and_sort(self):
        expected_observer_number = len(self.ordered_observers_list)
        self._wait_for_all_subscribers(expected_observer_number)
        self.logger.debug('%s all observers subscribed to flow' % self)
        ordered_subsribed_data = []
        if len(self._subscribed_observers) == len(self.ordered_observers_list):
            # todo refactor sorting subscribed_observers_data
            for index, observer in enumerate(self.ordered_observers_list):
                for observer_data in self._subscribed_observers:
                    if observer_data.msg_queue == observer.msg_queue:
                        ordered_subsribed_data.append(observer_data)
            self._subscribed_observers = ordered_subsribed_data

        else:
            raise Exception('sorting subsribed observers too fast')

    def _wait_for_all_subscribers(self, expected_observer_number):
        # todo teardown of this waiting should be done by flow timeout
        self.logger.debug('%s waiting for %s observers to subscribe' % (self, expected_observer_number))
        while len(self._subscribed_observers) != expected_observer_number:
            time.sleep(0.1)

    def _update_active_observer(self):
        try:
            self._observer_list_lock.acquire()
            if len(self._subscribed_observers) == 0:
                self.logger.debug('%s updating observers noticed that flow has already succeeded' % self)
                self._on_success()
                self._exit_flow_loop()
            else:
                if self._active_observer is None or self._active_observer != self._subscribed_observers[0]:
                    self._active_observer = self._subscribed_observers[0]
                    self.logger.debug('%s changed active observer to %s' % (self, self._active_observer))
            self._observer_list_lock.release()
        except Exception as e:
            self.logger.debug('%s error in updating active observer occured, releasing observer list lock' % self)
            self._observer_list_lock.release()
            raise e

    def _send_message_to_proper_subscribers(self, unparsed_message):
        if self._is_matching(self._active_observer, unparsed_message):  # and do_exist_in_subsribed:
            if self._active_observer.is_running.is_set():
                self._active_observer.msg_queue.put(unparsed_message)
                self.logger.debug('%s forwarding message %s to %s' %
                                  (self, unparsed_message, self._active_observer))
                return True
            else:
                self.logger.debug("%s not forwarded message %s to active %s since is has already ended (it should happen rarely!)" %
                                  (self, unparsed_message, self._active_observer))
                return False
        else:
            self.logger.debug("%s not forwarded message %s to active %s since they don't match" %
                              (self, unparsed_message, self._active_observer))
            return False

    def _is_matching(self, observer_data, message):
        if observer_data.owner == message.owner and observer_data.message_type == message.message_type:
            return True
        else:
            return False

    def _create_tree_of_observers(self):
        tree = {}
        for desc, observer in list(zip(self.flow_items, self.ordered_observers_list)):
            owner_dict = tree.get(desc.owner.alias, {})
            message_type_list = owner_dict.get(desc.message_type, [])
            message_type_list.append(observer)
            owner_dict[desc.message_type] = message_type_list
            tree[desc.owner.alias] = owner_dict
        return tree

    def _create_aliases_to_observers_mapping(self):
        mapping = {}
        for desc, observer in list(zip(self.flow_items, self.ordered_observers_list)):
            if desc.alias:
                mapping[desc.alias] = observer
        return mapping

    def _get_message_from_flow(self, message_owner_alias, message_type, occurrence):
        """
        :param message_owner: MessageOwner class instance
        :param message_type:
        :param occurrence: no occurence can be provided only if have only one message of given type
        :return: Message class instance

        MessageOwner class instance can be used as a key in dict only when being singleton by device_name and device_id
        If removing singleton is required, search must be changed to looping over dict keys and comparison.
        """
        occurrence = int(occurrence) if occurrence else None
        if message_owner_alias in self._hierarchical_structure_of_observers and \
           message_type in self._hierarchical_structure_of_observers[message_owner_alias]:
            if occurrence and (len(self._hierarchical_structure_of_observers[message_owner_alias][message_type]) >= occurrence):
                occurrence -= 1 if occurrence != -1 else -1
                return self._hierarchical_structure_of_observers[message_owner_alias][message_type][occurrence].get_message()
            elif not occurrence and len(self._hierarchical_structure_of_observers[message_owner_alias][message_type]) == 1:
                return self._hierarchical_structure_of_observers[message_owner_alias][message_type][-1].get_message()

        raise NoMessageInFlow(message_type)

    def _exit_flow_loop(self):
        self.is_running.clear()


def get_device_for_protocol(protocol_name):
    """
    Returns name of corresponding network element without device ID

    :param protocol_name: name of one of LTE protocols
    :return: network_element_name
    """
    PROTOCOLS = {'NR-RRC': 'UE',
                 'RRC': 'UE',
                 'S1AP': 'MME',
                 'X2AP': 'ENB',
                 'NAS': 'UE',
                 'M3AP': 'MME',
                 'NGAP': 'AMF',
                 'F1AP': 'GNB',
                 'E1AP': 'GNB',
                 'XNAP': 'GNB'}

    if protocol_name in PROTOCOLS:
        return PROTOCOLS[protocol_name]


def get_identification_for_protocol(protocol_name):
    """
    Gets the identification per protocol
    """
    DEVICES_IDENTIFICATION = {
        'UE': UeIdentification,
        'MME': MmeIdentification,
        'AMF': AmfIdentification,
        'ENB': EnbIdentification,
        'GNB': GnbIdentification
    }

    protocol_name = str(protocol_name).upper()
    device = get_device_for_protocol(protocol_name)
    return DEVICES_IDENTIFICATION[device]


class ExpectedMessageDescription(object):
    """
    Receives parsed single line flow description and stores it.
    Used during flow startup only when list of single flow items is gathered.
    """
    _verification_sentence_record = namedtuple(typename='Verification_sentence_record',
                                               field_names='full_sentence split_sentence')

    @staticmethod
    def _parse_verification_sentence(self, ver_callback):
        """
        :param verififcation sentence, everything inside () brackets with brackets itself
        :param ver_callback: entire verification sentence inside a list e.g. ['aabb xx']
        :return: namedtuple record with .full_sentence and .split_sentence attrs
        """
        sentence = ver_callback[0][1:-1]
        ExpectedMessageDescription._verification_sentence_record(sentence, sentence.split())
        return ExpectedMessageDescription._verification_sentence_record(sentence, sentence.split())

    @staticmethod
    def _parse_condition_type(self, sentence):
        sentence = sentence[0]
        condition = None
        for acceptable_condition in CapturingCondition.allowed_capturing_conditions:
            result = re.match(acceptable_condition['regexp_str'], sentence)
            if result:
                condition_type = acceptable_condition['type']
                condition_param_values = list(result.groups())
                condition = CapturingCondition(name=condition_type, params_list=condition_param_values)
                break
            else:
                continue
        if not condition:
            raise CatchingConditionNotSupported('The condition {} is not supported, only {} are implemented'
                                                .format(sentence, [CapturingCondition.get_list_of_possible_conditions_regexp_strings()]))
        return condition

    # device matching patter e.g. MME, MME-1
    _device = pyparsing.Word(pyparsing.alphanums + '_')
    _device_message_protocol_sep = pyparsing.Suppress(pyparsing.Literal(":"))

    # message type with protocol matching RRC_someMessage
    _message_protocol = pyparsing.Word(pyparsing.alphanums + '-')
    _message_protocol_type_sep = pyparsing.Suppress(pyparsing.Literal("_"))
    # message_type could be e.g. 'Paging' or 'Paging-r11' for multi/broadcast purposes
    _message_type = pyparsing.Word(pyparsing.alphanums + '-')
    # message catching on given condition requested
    _generic_parsing_regexp_str = \
        r'(' + str("|".join(CapturingCondition.get_list_of_possible_conditions_regexp_strings())) + r')'
    _message_catching_on_condition = pyparsing.Suppress('caught') + pyparsing.Regex(_generic_parsing_regexp_str)\
        .setParseAction(_parse_condition_type.__func__)
    # sentence within (..) brackets with brackets
    _veryfication_sentence = pyparsing.Regex(r'\(.*\)').setParseAction(_parse_verification_sentence.__func__)
    # name used after 'as' word
    _alias_name = pyparsing.Suppress('as') + pyparsing.Word(pyparsing.alphanums + '_' + '-')
    # Group used to have constant length list as return (even if optional items not provided)
    # e.g. UE_1:RRC_AAA ((a=b) and d) as RR
    _robot_line_template = pyparsing.Group(pyparsing.Optional(_device + _device_message_protocol_sep)) \
        + _message_protocol \
        + _message_protocol_type_sep \
        + _message_type \
        + pyparsing.Group(pyparsing.Optional(_message_catching_on_condition)) \
        + pyparsing.Group(pyparsing.Optional(_veryfication_sentence)) \
        + pyparsing.Group(pyparsing.Optional(_alias_name))
    # template used to verify if line contains string that is allowed to be an alias: anyTextAsAlias, some_alias
    _alias_template = pyparsing.Word(pyparsing.alphanums + '_')
    # template used to retrieve message from flow e.g. MME:RCC_AAA, MME-1:RRC_AAA, RRC_AAA, RRC_AAA[2], anyTextAsAlias
    _message_getter_template = pyparsing.Group(pyparsing.Optional(_device + _device_message_protocol_sep)) \
        + _message_protocol \
        + _message_protocol_type_sep \
        + _message_type \
        + pyparsing.Group(pyparsing.Optional(pyparsing.Suppress('[')
                                             + pyparsing.Regex(r'\d+')
                                             + pyparsing.Suppress(']')))

    def __init__(self, device, protocol, message_type, catching_condition=None, verification_sentences=None, alias=None, occurrence=None):
        self.protocol = protocol
        self.message_type = message_type
        self.logger = logging.getLogger('messaging.flows')
        self.logger_msgs = logging.getLogger('messaging.flows.logic')
        self.catching_condition = catching_condition if catching_condition else None
        self._verify_message_type()
        self.verification_callback = self._create_callback(verification_sentences)
        self.device = device if device else None  # can be empty list
        self.alias = alias if alias else None
        self.occurrence = occurrence if occurrence else None
        self.owner = self._get_owner()

    def _verify_message_type(self):
        if protocol_exists(self.protocol):
            if not message_exists_in_protocol(self.message_type, self.protocol):
                raise MessageTypeDoesNotExistInProtocol('Message {} does not exists inside protocol {}, possible values {}'
                                                        .format(self.message_type,
                                                                self.protocol,
                                                                all_messages_in_protocol(self.protocol)))
        else:
            raise ProtocolNotSupported('Protocol {} not supported, only {} values possible'.format(self.protocol,
                                                                                                   supported_protocols()))

    def _get_owner(self):
        device_type = get_device_for_protocol(self.protocol)
        create_owner_fun = getattr(self, '_create_%s_owner' % device_type.lower())
        owner = create_owner_fun()
        return owner

    def _get_running_dynamic_sources(self):
        dynamic_sources = []
        for src in list(aliases_registry().values()):
            if hasattr(src, 'network_elem_identifier') and hasattr(src.network_elem_identifier, 'specific_for_tool') \
                    and src.network_elem_identifier.specific_for_tool is not None:
                if DYNAMIC_SOURCE_SUFFIX in src.network_elem_identifier.specific_for_tool:
                    dynamic_sources.append(src)
        self.logger.debug('Found running dynamic sources: {}'.format(dynamic_sources))
        return dynamic_sources

    def _get_types_of_running_dynamic_sources(self):
        return [src.network_elem_identifier.network_elem_type for src in self._get_running_dynamic_sources()]

    def _filter_dynamic_src_regexp_with_running_sources(self):
        regexpes = {}
        started_dynamic_types = self._get_types_of_running_dynamic_sources()
        for reg in list(DYNAMIC_SOURCE_REGEXPS.keys()):
            if reg in started_dynamic_types:
                regexpes[reg] = DYNAMIC_SOURCE_REGEXPS[reg]
        return regexpes

    def _get_dynamic_source_identification(self):
        matches_idents = []
        dynamic_regexpes = self._filter_dynamic_src_regexp_with_running_sources()
        for ident in list(dynamic_regexpes.keys()):
            if DYNAMIC_SOURCE_REGEXPS[ident].search(self.device):
                matches_idents.append(ident)
        assert len(matches_idents) < 2, 'Used alias: {} matches both UE (e.g. MY_UE_1) and CELL (e.g. MY_CELL_2_3),\
         do not use _NUMBER notation in global alias declaration'
        if len(matches_idents) == 1:
            dynamic_source_name = DYNAMIC_SOURCE_REGEXPS[matches_idents[0]].sub(r'\1', self.device)
            alias_of_source = dynamic_source_name + "__identification"
            dynamic_source = aliases_registry()[alias_of_source] if alias_of_source in aliases_registry() else None
        else:
            dynamic_source = None
        return dynamic_source

    def _remove_dynamic_source_suffix(self, tool_specific_id):
        return re.sub(DYNAMIC_SOURCE_SUFFIX, '', tool_specific_id)

    def _exctract_id_from_dynamic_source_alias(self, identification):
        if identification.network_elem_type == 'UE':
            regexp = DYNAMIC_SOURCE_REGEXPS['UE']
            res = regexp.search(self.device)
            if res:
                return int(res.group(2))  # from MY_UE_1 returns '1', first group used for matching last name character
        elif identification.network_elem_type == 'CELL':
            regexp = DYNAMIC_SOURCE_REGEXPS['CELL']
            res = regexp.search(self.device)
            if res:
                return {'enb_id': res.group(2), 'cell_id': res.group(3)}   # first group used for matching last name character
        else:
            raise UnknownAlias('Cannot extract ids for dynamic alias: {}:{}'.format(type(identification), identification))

    def _create_dynamic_ne(self):
        dynamic_source = self._get_dynamic_source_identification()
        if dynamic_source is not None:
            self.logger.info('Matched dynamic source : {} for alias: {}'.format(dynamic_source, self.device))
            old_id_type = dynamic_source.network_elem_identifier.specific_for_tool
            new_id_type = self._remove_dynamic_source_suffix(old_id_type)
            new_id = self._exctract_id_from_dynamic_source_alias(dynamic_source.network_elem_identifier)
            new_dynamic_source_with_id = copy.deepcopy(dynamic_source)
            del new_dynamic_source_with_id.network_elem_identifier[old_id_type]
            new_dynamic_source_with_id.network_elem_identifier[new_id_type] = new_id
            new_dynamic_source_with_id.network_elem_identifier['alias'] = self.device
            new_dynamic_source_with_id.network_elem_identifier.specific_for_tool = new_id_type
            self.logger.info('Creating dynamic identification :{} for alias: {}'.format(new_dynamic_source_with_id, self.device))
            network_element = new_dynamic_source_with_id
        else:
            network_element = None
        return network_element

    def _create_ue_owner(self):
        # NOTICE: it applies for UEIdentification and for CellIdentification
        str_device = self.device
        if str_device:
            #########################################################################################################
            # to allow for having 2 entries for UE-alias inside common aliases_registry (which checks uniqueness)
            #
            # Require Ue          UE_ALIAS_1    capabilities=CAT6
            # Create UE alias     UE_ALIAS_1    ue_id=9            id_type=wts
            #
            # Since 'Create UE alias' is temporary solution required for messaging we need both keywords.
            # And since we want to keep all aliases in common aliases_registry:
            #   we need following trick to split logically same alias into two:
            #   1) UE_ALIAS_1                 - first line registers LteUe object under this alias
            #   2) UE_ALIAS_1__identification - second line registers LteNetworkElement(UeIdentification) object
            ########################################################################################################
            alias_for_identification = str_device + "__identification"
            if alias_for_identification in aliases_registry():
                network_element = aliases_registry()[alias_for_identification]
            else:
                network_element = self._create_dynamic_ne()
                if network_element is None:
                    raise UnknownAlias('Alias: {} not created and not found among dynamic message sources'.format(str_device))
                else:
                    aliases_registry()[alias_for_identification] = network_element
        else:
            ue_instances = [ue for ue in list(aliases_registry().values()) if ue.network_elem_identifier.network_elem_type == 'UE']
            if len(ue_instances) > 1:
                raise MessageDescriptionNotSufficient('Message owner (device) has to be defined in flow definition for msg: %s' % (self.message_type))
            else:
                network_element = ue_instances[0]
        identyfication_instance = network_element.network_elem_identifier
        return identyfication_instance

    def _create_mme_owner(self):
        str_device = self.device
        if str_device:
            network_element = aliases_registry()[str_device]
        else:
            mme_instances = [mme for mme in list(aliases_registry().values()) if mme.network_elem_identifier.network_elem_type == 'MME']
            if len(mme_instances) > 1:
                raise MessageDescriptionNotSufficient(
                    'Message owner (device) has to be defined in flow definition for msg: %s' % (self.message_type))
            else:
                network_element = mme_instances[0]
        identyfication_instance = network_element.network_elem_identifier
        return identyfication_instance

    def _create_amf_owner(self):
        str_device = self.device
        if str_device:
            network_element = aliases_registry()[str_device]
        else:
            amf_instances = [amf for amf in list(aliases_registry().values()) if amf.network_elem_identifier.network_elem_type == 'AMF']
            if len(amf_instances) > 1:
                raise MessageDescriptionNotSufficient(
                    'Message owner (device) has to be defined in flow definition for msg: %s' % (self.message_type))
            else:
                network_element = amf_instances[0]
        identyfication_instance = network_element.network_elem_identifier
        return identyfication_instance

    def _create_enb_owner(self):
        str_device = self.device
        if str_device:
            network_element = aliases_registry()[str_device]
        else:
            enb_instances = [enb for enb in list(aliases_registry().values()) if enb.network_elem_identifier.network_elem_type == 'ENB']
            if len(enb_instances) > 1:
                raise MessageDescriptionNotSufficient(
                    'Message owner (device) has to be defined in flow definition for msg: %s' % (self.message_type))
            else:
                network_element = enb_instances[0]
        identyfication_instance = network_element.network_elem_identifier
        return identyfication_instance

    def _create_gnb_owner(self):
        str_device = self.device
        if str_device:
            network_element = aliases_registry()[str_device]
        else:
            gnb_instances = [gnb for gnb in list(aliases_registry().values()) if gnb.network_elem_identifier.network_elem_type == 'GNB']
            if len(gnb_instances) > 1:
                raise MessageDescriptionNotSufficient(
                    'Message owner (device) has to be defined in flow definition for msg: %s' % (self.message_type))
            else:
                network_element = gnb_instances[0]
        identyfication_instance = network_element.network_elem_identifier
        return identyfication_instance

    def __str__(self):
        return "ExpectedMessageDescription(%s)" % vars(self)

    def _create_callback(self, verification_sentences):
        callback = self._create_callback_verification(verification_sentences)
        if self.catching_condition:
            callback = wrap_to_perform_conditional_capturing(callback, self.catching_condition)
        else:
            callback = wrap_to_parse_message_and_forward_to_verifier(callback)
        return callback

    @staticmethod
    def _always_true_callback_no_arguments():
        return True

    @staticmethod
    def _always_true_callback_msg_argument(msg):
        """
        This callback is needed for 'caught on change' conditional capturing, because raw message payload is needed for verifier to make a decision
        """
        return True

    def _create_callback_verification(self, verification_sentences):
        callback = None
        if verification_sentences:
            user_callback = self._if_user_callback(verification_sentences)
            if user_callback is not None:
                callback = user_callback
            else:
                query_parsed_verifier = message_query_parser().parse(input=verification_sentences.full_sentence)['action_result']
                wrapped_query_parsed_verifier = wrap_in_try_except(query_parsed_verifier, verification_sentences.full_sentence)
                callback = wrapped_query_parsed_verifier
        else:
            default_callback = self._create_default_callback()
            default_callback.__setattr__('__wrapped__', default_callback)
            callback = default_callback
        return callback

    def _is_unparsed_message_needed_in_default_callback(self):
        condition_types_needing_unparsed_message = ['on change']
        if self.catching_condition and self.catching_condition.condition_type in condition_types_needing_unparsed_message:
            return True
        else:
            return False

    def _create_default_callback(self):
        if self._is_unparsed_message_needed_in_default_callback() is False:
            return ExpectedMessageDescription._always_true_callback_no_arguments
        else:
            return ExpectedMessageDescription._always_true_callback_msg_argument

    def _if_user_callback(self, verification_sentences):
        _normalized_user_callback = self._normalize_to_user_callack(verification_sentences.full_sentence)

        if _normalized_user_callback in get_registered_verifiers():
            self.logger.debug("%s: Message verifier: %s found in registered verifiers" %
                              (self, _normalized_user_callback))
            return get_registered_verifiers()[_normalized_user_callback]
        else:
            # current solution when no automatic verifiers generation possible
            # in the future some grammar check on verifier generator should be applied and below error
            # should be rised when no automatic grammar parsing could be used nor user verifier registered
            # raise UserDefinedMessageVerifierDoesNotExist(_normalized_user_callback, get_registered_verifiers())
            self.logger_msgs.debug("Message verifier: {} supplied but NOT found in registered verifiers: {},"
                                   " consider using @message_verifier decorator to mark the verifier or check verifiers spelling"
                                   .format(_normalized_user_callback, get_registered_verifiers()))
            return None

    def _normalize_to_user_callack(self, verification_sentences):
        return str(re.sub('-| ', '_', verification_sentences)).lower()

    @staticmethod
    def wrap_message_description_to_structure(parsed_message2retrieval_description):
        """
        :param parsed_message2retrieval_description: output of parsing message for retrieval description.

        Contains device, protocol, message_type and optional: occurrence

        :return: ExpectedMessageDescription instance
        """

        return ExpectedMessageDescription(device=parsed_message2retrieval_description[0][0] if parsed_message2retrieval_description[0] else None,
                                          protocol=parsed_message2retrieval_description[1],
                                          message_type=parsed_message2retrieval_description[2],
                                          occurrence=parsed_message2retrieval_description[3][0] if parsed_message2retrieval_description[3] else None)

    @staticmethod
    def wrap_single_flow_sentence_to_structure(parsed_flow_input_line):
        """
        :param parsed_flow_input_line: output of parsing description of flow item
         Contains device, protocol, message_type and optional: verification condition and/or alias
        :return: ExpectedMessageDescription instance
        """
        return ExpectedMessageDescription(device=parsed_flow_input_line[0][0] if parsed_flow_input_line[0] else None,
                                          protocol=parsed_flow_input_line[1],
                                          message_type=parsed_flow_input_line[2],
                                          catching_condition=parsed_flow_input_line[3][0] if parsed_flow_input_line[3] else None,
                                          verification_sentences=parsed_flow_input_line[4][0] if parsed_flow_input_line[4] else None,
                                          alias=parsed_flow_input_line[5][0] if parsed_flow_input_line[5] else None)

    @staticmethod
    def parse_flow_robot_style_input_line(line):
        """
        Returns name of corresponding network element

        :param line: input line from robot file
        :return:  Description instance

        example of input lines::

            NAS_ExtendedServiceRequest
            UE_1:NAS_ExtendedServiceRequest
            UE_1:NAS_ExtendedServiceRequest as AA
            NAS_ExtendedServiceRequest (with a=v) as AA
            NAS_ExtendedServiceRequest (with a=v)
        """
        parsed_line = ExpectedMessageDescription._robot_line_template.parseString(line)  # list of 6 elements
        number_of_parsed_optional_elements = sum([1 for el in parsed_line[3:] if len(el)])  # catching condition/alias/verifier
        number_of_elements_in_pure_line = len(re.split(r'\s+', line))
        number_of_options_elements_in_pure_line = number_of_elements_in_pure_line - 1
        if number_of_options_elements_in_pure_line > 0 and number_of_parsed_optional_elements == 0:
            raise ExpectMessageFlowSyntaxError('Parser could not extract optional expect line parameters '
                                               'as catching condition/msg_alias/verifier,'
                                               ' because user line has incorrect additional data/syntax:\n{}'.format(line))
        return ExpectedMessageDescription.wrap_single_flow_sentence_to_structure(parsed_line)


class FlowItem(object):
    """
    Is used to store single flow item message description, its observer and original order.
    """
    def __init__(self, flow_item_description, order_index):
        self.description = ExpectedMessageDescription.parse_flow_robot_style_input_line(flow_item_description)
        self.order_index = order_index
        self.occurrence = None

    @property
    def verification_callback(self):
        """
        :return: verification callback
        """
        return self.description.verification_callback

    @property
    def message_type(self):
        """
        :return: message type of flow item
        """
        return self.description.message_type

    @property
    def protocol(self):
        """
        :return: message type of flow item
        """
        return self.description.protocol

    @property
    def alias(self):
        """
        :return: message internal alias of flow item
        """
        return self.description.alias

    @property
    def owner(self):
        """
        :return: message owner instance
        """
        return self.description.owner

    def __eq__(self, other):
        if (self.message_type == other.message_type) and (self.owner == other.owner):
            return True
        return False


def wrap_in_try_except(func, query):
    """
    Function for wrapping query parsed verifier into additional try/except to avoid library hanging.
    :param func:
    :param logger:
    :return: wrapped func
    """
    def _wrapped_func(*args, **kwargs):
        logger = logging.getLogger('messaging.flows')
        try:
            return func(*args, **kwargs)
        except Exception as e:
            logger.error('Error in query parsed verifier occurred: ({})'.format(repr(e)))
            return False
    _wrapped_func.__wrapped__ = func
    _wrapped_func.__query__ = query
    return _wrapped_func


